 const [holidayDate,setHolidayDate]=useState(""),[holidayName,setHolidayName]=useState(""),[message,setMessage]=useState("Loading leave records…"),[busy,setBusy]=useState(false);
 const load=async()=>{setBusy(true);try{const r=await leaveApi({action:"request.list"});setRequests(Array.isArray(r.requests)?r.requests:[]);try{const p=await leaveApi({action:"profile.list"});setEmployees(Array.isArray(p.employees)?p.employees:[]);}catch{}try{const a=await leaveApi({action:"audit.list",limit:30});setEvents(Array.isArray(a.events)?a.events:[]);}catch{}try{const h=await leaveApi({action:"calendar.holiday.list"});setHolidays(Array.isArray(h.holidays)?h.holidays:[]);}catch{}setMessage("Leave records refreshed.");}catch(e){setMessage(e instanceof Error?e.message:"Leave Tracker is unavailable. Sign in and confirm the backend database is configured.");}finally{setBusy(false)}};
