  <div className="section-title"><div><span className="kicker">PEOPLE OPERATIONS</span><h2>Leave Tracker</h2><p className="hint">Submit leave, review approvals, record return-to-work and maintain an auditable schedule.</p></div><button className="secondary" onClick={()=>void load()} disabled={busy}>↻ Refresh</button></div>
