  <details className="builder-source"><summary>HR / admin: holiday calendar</summary><div className="builder-actions"><label>Date<input className="tool-input" type="date" value={holidayDate} onChange={e=>setHolidayDate(e.target.value)}/></label><label>Holiday name<input className="tool-input" value={holidayName} onChange={e=>setHolidayName(e.target.value)} placeholder="Public holiday"/></label><button className="primary" disabled={busy||!holidayDate||!holidayName.trim()} onClick={()=>void run("calendar.holiday.save",{date:holidayDate,name:holidayName.trim()})}>Add holiday</button></div>{holidays.map((h:any)=><p key={h.date}>{h.date} · {h.name} ({h.region})</p>)}</details>
