 const clearArchiveNow=async()=>{if(vaultActionBusy)return;if(!window.confirm(`Permanently remove all ${vaultArchive.length} encrypted file(s) from this browser archive? This does not delete original files or downloaded copies.`))return;setVaultActionBusy(true);try{const count=await clearVaultArchive();await appendVaultAudit({action:"clear-archive",outcome:"success",fileName:"ALL ARCHIVE ITEMS",fileSize:0,detail:`Cleared ${count} encrypted archive item(s).`});if(vaultPreviewUrl){URL.revokeObjectURL(vaultPreviewUrl);setVaultPreviewUrl("");setVaultPreviewName("");}await refreshVaultArchive();setStatus(`Archive cleared. ${count} item(s) removed; original and downloaded copies were not affected.`);}catch(e){setStatus(e instanceof Error?e.message:"Could not clear the archive.");}finally{setVaultActionBusy(false);}};
 const clearAuditNow=async()=>{if(vaultActionBusy)return;if(!window.confirm(`Clear all ${vaultAudit.length} Vault audit event(s)? A new audit entry will be written to record that the log was cleared.`))return;setVaultActionBusy(true);try{const count=await clearVaultAudit();await appendVaultAudit({action:"clear-audit",outcome:"success",fileName:"VAULT AUDIT LOG",fileSize:0,detail:`Cleared ${count} prior audit event(s). This entry records the clearing operation.`});await refreshVaultArchive();setStatus(`Audit log cleared. ${count} prior event(s) removed; a new record of this action was retained.`);}catch(e){setStatus(e instanceof Error?e.message:"Could not clear the audit log.");}finally{setVaultActionBusy(false);}};
