 const archiveSelectedFile=async(selected:File)=>{setVaultActionBusy(true);try{const header=await readVaultHeader(selected);const item=await archiveEncryptedFile(selected,selected.name,header.operationId);await appendVaultAudit({action:"archive",outcome:"success",fileName:item.name,fileSize:item.size,detail:"Encrypted file imported into this browser archive."});await refreshVaultArchive();setStatus("Encrypted file archived on this device. It remains encrypted; use its password to preview or decrypt.");}catch(e){await appendVaultAudit({action:"archive",outcome:"failure",fileName:selected.name,fileSize:selected.size,detail:e instanceof Error?e.message:"Invalid encrypted file."}).catch(()=>{});setStatus(e instanceof Error?e.message:"Could not archive encrypted file.");}finally{setVaultActionBusy(false);}};
 const archiveAction=async(item:VaultArchiveItem,action:"preview"|"download"|"decrypt"|"remove")=>{setVaultActionBusy(true);try{if(action==="remove"){if(!window.confirm("Remove this encrypted file from this browser archive? This does not delete any downloaded copies."))return;await removeVaultArchive(item.id);await appendVaultAudit({action:"remove",outcome:"success",fileName:item.name,fileSize:item.size});await refreshVaultArchive();setStatus("Encrypted archive item removed.");return;}if(action==="download"){downloadBlob(item.blob,item.name);await appendVaultAudit({action:"download",outcome:"success",fileName:item.name,fileSize:item.size,detail:"Encrypted file downloaded."});setStatus("Encrypted file download started.");await refreshVaultArchive();return;}if(!password){setStatus("Enter the file password above before previewing or decrypting.");return;}const restored=await decryptArchivedFile(item,password);if(action==="preview"){if(vaultPreviewUrl)URL.revokeObjectURL(vaultPreviewUrl);const url=URL.createObjectURL(restored.blob);setVaultPreviewUrl(url);setVaultPreviewName(restored.name);if(restored.type==="application/octet-stream")setStatus("Password verified. This file type may not preview in the browser; use Download decrypted file.");else setStatus("Password verified and file integrity checked. Preview is ready below.");await appendVaultAudit({action:"preview",outcome:"success",fileName:item.name,fileSize:item.size,detail:"Password verified; plaintext preview generated locally."});}else{downloadBlob(restored.blob,restored.name);await appendVaultAudit({action:"decrypt",outcome:"success",fileName:item.name,fileSize:item.size,detail:"Password verified; decrypted file downloaded."});setStatus("Decryption and integrity verification succeeded; download started.");}await refreshVaultArchive();}catch(e){await appendVaultAudit({action:action==="preview"?"preview":"decrypt",outcome:"failure",fileName:item.name,fileSize:item.size,detail:e instanceof Error?e.message:"Operation failed."}).catch(()=>{});setStatus(e instanceof Error?e.message:"Vault operation failed. Check the password and file integrity.");await refreshVaultArchive();}finally{setVaultActionBusy(false);}};
 const add=(op:string,name:string,status:string)=>{const l={id:crypto.randomUUID(),op,file:name,time:new Date().toISOString(),status};const n=[l,...logs];setLogs(n);saveLogs(n)};
 const run=async(op:"encrypt"|"decrypt")=>{
  if("__TAURI_INTERNALS__" in window){const input=await open({multiple:false,directory:false,title:op==="encrypt"?"Choose file to encrypt":"Choose .nsv file to decrypt"});if(!input||Array.isArray(input))return;const name=String(input).split(/[\\/]/).pop()||"file";const suggested=op==="encrypt"?"nexora-vault-"+crypto.randomUUID()+".nsv":String(await invoke("inspect_nsv1_name",{input:String(input),password}));const output=await save({defaultPath:suggested,title:op==="encrypt"?"Save encrypted vault":"Save decrypted file"});if(!output)return;setBusy(true);setProgress(0);setStatus(op==="encrypt"?"Encrypting with AES-256-GCM…":"Decrypting and verifying integrity…");try{await invoke(op==="encrypt"?"encrypt_nsv1":"decrypt_nsv1",op==="encrypt"?{input:String(input),output,password,fileName:name,createdAt:new Date().toISOString(),operationId:crypto.randomUUID().replace(/-/g,"")}:{input:String(input),output,password});add(op,name,"Success");setProgress(100);setStatus(op==="encrypt"?"Vault created successfully.":"File restored and integrity verified.")}catch(e){add(op,name,"Failed");setStatus(e instanceof Error?e.message:"Operation failed")}finally{setBusy(false);setPassword("")}return}
  if(!file||!password){setStatus("Select a file and enter a password.");return}cancel.current=new AbortController();setBusy(true);setProgress(0);setStatus(op==="encrypt"?"Encrypting locally…":"Decrypting locally…");try{const total=file.size;const update=(n:number)=>setProgress(total===0?100:Math.min(100,Math.round(n/total*100)));if(op==="encrypt"){const outputParts:Uint8Array[]=[];const r=await encryptBrowserFile(file,password,update,cancel.current.signal,chunk=>outputParts.push(chunk));const encryptedBlob=new Blob(outputParts,{type:"application/octet-stream"});const archived=await archiveEncryptedFile(encryptedBlob,r.outputName,r.header.operationId);await appendVaultAudit({action:"encrypt",outcome:"success",fileName:archived.name,fileSize:archived.size,detail:"Encrypted locally and saved to this browser archive."});add(op,archived.name,"Success");await refreshVaultArchive();setStatus("Vault created, downloaded and archived on this device.")}else{const r=await decryptBrowserFile(file,password,update,cancel.current.signal);await appendVaultAudit({action:"decrypt",outcome:"success",fileName:r.header.originalName,fileSize:file.size,detail:"Password verified and file integrity checked."});add(op,r.header.originalName,"Success");await refreshVaultArchive();setStatus("File restored and integrity verified.")}}catch(e){const msg=e instanceof DOMException&&e.name==="AbortError"?"Operation cancelled":e instanceof Error?e.message:"Operation failed";add(op,file.name,msg==="Operation cancelled"?"Cancelled":"Failed");setStatus(msg)}finally{cancel.current=null;setBusy(false);setPassword("")}
 };

 useEffect(()=>{let cancelled=false;try{const request=indexedDB.open("nexora-voice-library",1);request.onupgradeneeded=()=>{const db=request.result;if(!db.objectStoreNames.contains("voices"))db.createObjectStore("voices",{keyPath:"id"});};request.onsuccess=()=>{const db=request.result;const tx=db.transaction("voices","readonly");const get=tx.objectStore("voices").getAll();get.onsuccess=()=>{if(!cancelled&&Array.isArray(get.result)){setVoiceLibrary(get.result);const first=get.result[0];if(first&&!videoVoiceReference)setVideoVoiceReference({name:first.name,dataUrl:first.dataUrl});}};};}catch{}return()=>{cancelled=true};},[]);
 const persistImportedVoice=async(file:File)=>{if(!file.type.startsWith("audio/"))throw new Error("Choose an audio file for a voice sample.");if(file.size>5_000_000)throw new Error("Voice samples must be 5 MB or smaller.");const sample=await readReferenceFile(file,5_000_000);const voice={id:crypto.randomUUID(),name:customVoiceName.trim()||file.name.replace(/\\.[^.]+$/,""),filename:file.name,dataUrl:sample.dataUrl,createdAt:new Date().toISOString()};await new Promise<void>((resolve,reject)=>{const request=indexedDB.open("nexora-voice-library",1);request.onupgradeneeded=()=>{if(!request.result.objectStoreNames.contains("voices"))request.result.createObjectStore("voices",{keyPath:"id"});};request.onerror=()=>reject(new Error("Could not open local voice library."));request.onsuccess=()=>{const db=request.result;const tx=db.transaction("voices","readwrite");tx.objectStore("voices").put(voice);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(new Error("Could not save voice sample to this browser."));};});setVoiceLibrary(items=>[voice,...items.filter(x=>x.id!==voice.id)]);setVideoVoiceReference({name:voice.name,dataUrl:voice.dataUrl});setCustomVoiceName(voice.name);setStatus("Voice imported and saved in this browser's private Nexora voice library.");};
 const selectImportedVoice=(id:string)=>{const voice=voiceLibrary.find(x=>x.id===id);setVideoVoiceReference(voice?{name:voice.name,dataUrl:voice.dataUrl}:null);if(voice)setCustomVoiceName(voice.name);};
 const removeImportedVoice=async(id:string)=>{await new Promise<void>((resolve,reject)=>{const request=indexedDB.open("nexora-voice-library",1);request.onerror=()=>reject(new Error("Could not open voice library."));request.onsuccess=()=>{const db=request.result;const tx=db.transaction("voices","readwrite");tx.objectStore("voices").delete(id);tx.oncomplete=()=>{db.close();resolve()};tx.onerror=()=>reject(new Error("Could not remove voice."));};});const remaining=voiceLibrary.filter(x=>x.id!==id);setVoiceLibrary(remaining);if(voiceLibrary.find(x=>x.id===id)?.dataUrl===videoVoiceReference?.dataUrl)setVideoVoiceReference(remaining[0]?{name:remaining[0].name,dataUrl:remaining[0].dataUrl}:null);};
 const createMusic=async()=>{if(!musicPrompt.trim()&&!musicLyrics.trim()&&!musicReference){setMusicStatus("Describe the song, provide lyrics, or upload an authorized reference track.");return;}if(musicReference&&!musicReferenceRights){setMusicStatus("Confirm that you own or have permission to use the reference recording before continuing.");return;}setMusicBusy(true);setMusicResult("");setMusicStatus("Submitting music-generation job…");try{const prompt=[musicPrompt.trim(),musicLyrics.trim()?"Lyrics to sing (use only these lyrics or original additions explicitly requested):\\n"+musicLyrics.trim():"",musicInstrumental?"Instrumental only; no vocals.":"Generate a complete song with a coherent beginning, verses, chorus and ending.",musicBeatOnly?"Use the reference for high-level rhythm/tempo/instrumentation only; create an original arrangement, melody and lyrics.":"Create an original composition. Do not reproduce copyrighted lyrics, melody, or a recording.", "Genre: "+musicGenre+". Mood: "+musicMood+". Target length: "+musicDuration+" seconds. Tempo: "+musicBpm+" BPM (maintain this target tempo throughout unless a transition is explicitly part of the arrangement). Key: "+musicKey+". Scale/mode: "+musicScale+". Chord progression: "+(musicProgression==="Custom progression"?customMusicProgression:musicProgression)+". Structure: "+musicStructure+". Intro direction: "+(musicIntro.trim()||"provider interpretation")+". Interlude direction: "+(musicInterlude.trim()||"provider interpretation")+". Outro direction: "+(musicOutro.trim()||"provider interpretation")+". Selected instruments: "+[...musicInstruments,...customMusicInstruments.split(",").map(x=>x.trim()).filter(Boolean)].join(", ")+". Instrument arrangement: "+musicInstrumentDirection+". Instruments to exclude: "+(excludedMusicInstruments.trim()||"none specified")+". Deliver polished, balanced audio with a clear intro, transitions, complete ending and no abrupt cutoff."].filter(Boolean).join("\\n\\n");const leadVoice=voiceLibrary.find(v=>v.id===musicLeadVoiceId)||(musicLeadVoiceId===""&&videoVoiceReference?{...videoVoiceReference}:undefined);const backupVoices=musicBackupVoiceIds.map(id=>voiceLibrary.find(v=>v.id===id)).filter((v):v is {id:string;name:string;filename:string;dataUrl:string;createdAt:string}=>Boolean(v));const vocalDirection=musicInstrumental?"Instrumental only; no vocals.":"LEAD VOCALIST: "+(leadVoice?.name||"provider/default lead voice")+". Lead singer instructions: "+musicLeadVoiceDirection+". Keep this singer on the main melody, prominent and centered. BACKUP SINGERS: "+(backupVoices.length?backupVoices.map(v=>v.name+" (direction: "+(backupVoiceDirections[v.id]||"supporting harmonies and call-and-response; lower in mix than lead")+". assigned lines: "+(backupVoiceLyrics[v.id]||"harmonies or ad-libs where suitable")+")").join("; "):"none selected")+". Keep every singer in the assigned role; do not substitute a backup singer for the lead. Mix backing vocals below the lead.";const r=await createJob("music",{title:musicTitle,prompt:prompt+"\n\nVOCAL ARRANGEMENT: "+vocalDirection,genre:musicGenre,durationSeconds:Number(musicDuration),bpm:Number(musicBpm),key:musicKey,scale:musicScale,chordProgression:musicProgression==="Custom progression"?customMusicProgression:musicProgression,customChordProgression:customMusicProgression,mood:musicMood,structure:musicStructure,introDirection:musicIntro,interludeDirection:musicInterlude,outroDirection:musicOutro,arrangementSections:{intro:musicIntro,interlude:musicInterlude,outro:musicOutro},instruments:[...musicInstruments,...customMusicInstruments.split(",").map(x=>x.trim()).filter(Boolean)].slice(0,24),customInstruments:customMusicInstruments,instrumentDirection:musicInstrumentDirection,excludedInstruments:excludedMusicInstruments,lyrics:musicLyrics,instrumental:musicInstrumental,beatOnly:musicBeatOnly,voiceReferenceAudio:leadVoice?.dataUrl,voiceName:leadVoice?.name,leadVocalist:{name:leadVoice?.name,audio:leadVoice?.dataUrl,direction:musicLeadVoiceDirection},backupVoiceReferences:backupVoices.map(v=>({name:v.name,audio:v.dataUrl,lyrics:backupVoiceLyrics[v.id]||"",direction:backupVoiceDirections[v.id]||"Backing singer: supporting harmonies and call-and-response only where appropriate; remain lower in the mix than the lead."})),referenceTrackAudio:musicReference?.dataUrl,referenceTrackName:musicReference?.name,referenceRightsConfirmed:musicReferenceRights});const id=(r.job as {id?:string}|undefined)?.id;if(!id)throw new Error("No music job ID returned");const job=await waitForJob(id,undefined,1_800_000,phase=>setMusicStatus("Music generation "+phase.replace(/[_-]/g," ")+"…"));const result=job.result as {key?:string;audioBase64?:string;format?:string}|undefined;if(result?.audioBase64)setMusicResult("data:"+(result.format||"audio/mpeg")+";base64,"+result.audioBase64);else if(result?.key){const asset=await getAsset(result.key);if(typeof asset.url!=="string")throw new Error("No downloadable audio URL returned");setMusicResult(asset.url);}else throw new Error("Music provider returned no playable audio.");setMusicStatus("Music created successfully. Preview it below and download the finished track.");}catch(e){setMusicStatus(e instanceof Error?e.message:"Music generation unavailable.");}finally{setMusicBusy(false)}};
 const addMusicReference=async(file:File|null)=>{if(!file)return;if(!file.type.startsWith("audio/")){setMusicStatus("Choose an audio recording for the reference track.");return;}if(file.size>12_000_000){setMusicStatus("Reference tracks must be 12 MB or smaller.");return;}try{setMusicReference(await readReferenceFile(file,12_000_000));setMusicStatus("Reference track imported. Confirm that you have rights to use it before generating.");}catch(e){setMusicStatus(e instanceof Error?e.message:"Could not import reference track.");}};
