 const send=async()=>{if(!chatInput.trim()||aiBusy||!activeConversationId)return;const conversationId=activeConversationId;const user:ChatMessage={id:crypto.randomUUID(),role:"user",content:chatInput.trim(),createdAt:new Date().toISOString()};const answerId=crypto.randomUUID();const placeholder:ChatMessage={id:answerId,role:"assistant",content:"",createdAt:new Date().toISOString()};const next=[...chat,user,placeholder];setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:next,title:c.title==="New chat"?user.content.slice(0,42):c.title,updatedAt:new Date().toISOString()}:c));setChatInput("");setAiBusy(true);try{const r=await aiChatStream([...chat,user],model,(content)=>setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:c.messages.map(item=>item.id===answerId?{...item,content}:item),updatedAt:new Date().toISOString()}:c)));const finalContent=r.content||r.message||"No response returned.";setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:c.messages.map(item=>item.id===answerId?{...item,content:finalContent}:item),updatedAt:new Date().toISOString()}:c))}catch(e){const errorText=e instanceof Error?e.message:"AI service unavailable. Configure the secure AI endpoint.";setConversations(current=>current.map(c=>c.id===conversationId?{...c,messages:c.messages.map(item=>item.id===answerId?{...item,content:errorText}:item),updatedAt:new Date().toISOString()}:c))}finally{setAiBusy(false)}};
