 const addWorkflow=()=>{if(!workflowName.trim()||!workflowInput.trim())return;setWorkflows(items=>[{id:crypto.randomUUID(),name:workflowName.trim(),tool:workflowTool,input:workflowInput.trim(),createdAt:new Date().toISOString()},...items]);setWorkflowName("");setWorkflowInput("");setWorkflowStatus("Workflow saved in this browser. Use Run now to execute it through the configured Nexora AI endpoint.")};
 const runWorkflow=async(w:Workflow)=>{setWorkflowBusy(w.id);setWorkflowStatus("Running "+w.name+"…");try{const result=await aiTool(w.tool,w.input);const output=result.content||result.message||JSON.stringify(result.data??result,null,2);setWorkflows(items=>items.map(x=>x.id===w.id?{...x,lastRun:new Date().toISOString(),lastResult:output}:x));setWorkflowStatus("Completed: "+w.name)}catch(e){const output=e instanceof Error?e.message:"Workflow failed";setWorkflows(items=>items.map(x=>x.id===w.id?{...x,lastRun:new Date().toISOString(),lastResult:output}:x));setWorkflowStatus(output)}finally{setWorkflowBusy("")}};
 const createWebsite=async()=>{if(!builderPrompt.trim())return;setBuilderBusy(true);setBuilderStatus("Generating a fast, responsive website…");try{const designId=crypto.randomUUID();const prompt="Act as a senior product designer and front-end engineer. Create a premium, responsive single-file HTML website or browser app with inline CSS and lightweight JavaScript, semantic accessible markup, and working core interactions. ORIGINALITY: invent a distinct visual identity specifically for this brief. Do not copy an existing site, app, brand, screenshot, or template. Do not reuse generic placeholder icons or repeat the same hero image across unrelated projects. Create project-specific CSS/SVG iconography, visual motifs, layout rhythm, palette, typography and image composition. Avoid simple palette swaps of familiar templates. Every visual should fit the audience and purpose. PREMIUM QUALITY: refined spacing, mobile-first responsiveness, accessible contrast, purposeful motion, polished focus states, useful alt text and realistic content. Avoid fake testimonials, dead controls, generic AI-looking imagery, and bloated code. Return ONLY complete HTML; no external libraries, lengthy explanations, placeholders, or embedded base64 data. PROJECT UNIQUENESS KEY: "+designId+" (creative cue only; do not display).\n\nUSER BRIEF:\n"+builderPrompt.trim();const r=await aiTool("code",prompt);let html=r.content||r.message||"";html=html.replace(/^\s*```(?:html)?\s*/i,"").replace(/\s*```\s*$/,"");if(!/<html[\s>]/i.test(html)||!/<body[\s>]/i.test(html))throw new Error("The AI did not return a complete HTML page. Try a more specific prompt.");setBuilderHtml(html);setBuilderStatus("Website generated. Preview it, add your images, then export or publish.");}catch(e){setBuilderStatus(e instanceof Error?e.message:"Website generation failed.");}finally{setBuilderBusy(false);}};
 const refineWebsiteWithAgent=async()=>{if(!builderHtml||!builderAgentInstruction.trim())return;setBuilderBusy(true);setBuilderStatus("Live AI agent is applying your requested changes…");try{const prompt="You are Nexora’s live website and application-building agent. Edit the existing single-file HTML app according to the user’s change request. Preserve working features and unrelated design decisions, fix bugs you notice, improve accessibility and responsive behavior, and return ONLY the complete updated HTML document. Do not use external libraries or fake API keys. If a backend is needed, clearly label configuration placeholders in the UI rather than claiming it is connected.\n\nCHANGE REQUEST:\n"+builderAgentInstruction.trim()+"\n\nEXISTING COMPLETE HTML:\n"+builderHtml;const r=await aiTool("code",prompt);let html=r.content||r.message||"";html=html.replace(/^\s*```(?:html)?\s*/i,"").replace(/\s*```\s*$/,"");if(!/<html[\s>]/i.test(html)||!/<body[\s>]/i.test(html))throw new Error("The AI agent did not return a complete HTML page. Try a smaller change request.");setBuilderHtml(html);setBuilderAgentInstruction("");setBuilderStatus("AI changes applied. Review the live preview before exporting or publishing.");}catch(e){setBuilderStatus(e instanceof Error?e.message:"AI agent could not update this project.");}finally{setBuilderBusy(false);}};
 const addFormField=()=>{const id="field-"+crypto.randomUUID().slice(0,8);setFormFields(items=>[...items,{id,label:"New question",type:formNewFieldType,required:false,options:formNewFieldType==="select"?"Option 1, Option 2":""}]);setFormPreview("");setFormStatus("Field added. Customize the label and options.");};
 const updateFormField=(id:string,patch:Partial<FormField>)=>{setFormFields(items=>items.map(field=>field.id===id?{...field,...patch}:field));setFormPreview("");};
 const getCurrentFormHtml=(endpoint="")=>formCodeMode?formHtmlCode:buildFormHtml(formTitle,formFields,endpoint,{headerImage:formHeaderImage,theme:formTheme});
 const loadGeneratedFormCode=()=>{setFormHtmlCode(buildFormHtml(formTitle,formFields,"__NEXORA_FORM_ENDPOINT__",{headerImage:formHeaderImage,theme:formTheme}));setFormCodeMode(true);setFormPreview("");setFormStatus("Generated HTML loaded into the code editor. Keep __NEXORA_FORM_ENDPOINT__ in the form action to connect published submissions to Nexora.");};
 const previewFormNow=()=>{const html=getCurrentFormHtml("");if(!html.trim()){setFormStatus("Enter or generate form HTML before previewing.");return;}setFormPreview(html);setFormStatus(formCodeMode?"Code preview updated. Review custom HTML before publishing.":"Preview updated. Database storage is connected automatically when you publish the form.");};
 const publishFormNow=async()=>{if(formCodeMode?!formHtmlCode.trim():(!formFields.length||formFields.some(f=>!f.label.trim()))){setFormStatus(formCodeMode?"Enter or generate form HTML before publishing.":"Add at least one question and give every question a label.");return;}setFormStatus("Publishing form and connecting its database…");try{const name=(formTitle.trim().toLowerCase().replace(/[^a-z0-9-]+/g,"-").replace(/^-+|-+$/g,"").slice(0,48)||"nexora-form");const html=formCodeMode?formHtmlCode:buildFormHtml(formTitle,formFields,"__NEXORA_FORM_ENDPOINT__",{headerImage:formHeaderImage,theme:formTheme});const result=await publishSite(name,html,formTitle);recordPublishReport(result);setFormStatus((result.message||"Publish request accepted.")+(result.frontendUrl?" Frontend: "+result.frontendUrl:"")+(result.auditPersisted?" Audit report saved to the Nexora database.":" Audit report is stored in this browser; server database persistence was unavailable."));}catch(e){setFormStatus(e instanceof Error?e.message:"Form publishing failed. Check your sign-in, database configuration, and publishing permissions.");}};
 const downloadFormHtml=()=>{const html=getCurrentFormHtml("");if(!html.trim()){setFormStatus("Enter or generate form HTML before exporting.");return;}setFormPreview(html);download(new TextEncoder().encode(html),(formTitle.trim().toLowerCase().replace(/[^a-z0-9]+/g,"-")||"nexora-form")+".html");setFormStatus(formCodeMode?"Custom form HTML downloaded. Verify any custom submission endpoint before using it.":"Standalone HTML downloaded. Automatic database connection is enabled for forms published through Nexora.");};
 const importBuilderFiles=async(files:FileList|File[])=>{const selected=Array.from(files).filter(f=>f.type.startsWith("image/"));if(!selected.length){setBuilderStatus("Choose image files such as PNG, JPG, WebP or GIF.");return;}const room=Math.max(0,8-builderImages.length);if(!room){setBuilderStatus("You can import up to 8 images per project.");return;}const batch=selected.slice(0,room);try{const loaded=await Promise.all(batch.map(file=>new Promise<{name:string;dataUrl:string}>((resolve,reject)=>{if(file.size>2_000_000){reject(new Error(file.name+" is larger than 2 MB. Please resize it and try again."));return;}const reader=new FileReader();reader.onload=()=>resolve({name:file.name,dataUrl:String(reader.result)});reader.onerror=()=>reject(new Error("Could not read "+file.name));reader.readAsDataURL(file);})));setBuilderImages(items=>[...items,...loaded]);setBuilderStatus("Imported "+loaded.length+" image(s). Tap Insert on an image to add it to the page.");}catch(e){setBuilderStatus(e instanceof Error?e.message:"Image import failed.");}};
 const insertBuilderImage=(item:{name:string;dataUrl:string})=>{const tag='<img src="'+item.dataUrl+'" alt="'+item.name.replace(/[&"<>]/g,"")+'" style="max-width:100%;height:auto;border-radius:16px" />';const at=builderHtml.toLowerCase().lastIndexOf("</body>");setBuilderHtml(at>=0?builderHtml.slice(0,at)+tag+builderHtml.slice(at):builderHtml+"\n"+tag);setBuilderStatus("Image inserted into your website HTML.");};
 const exportWebsite=()=>{if(!builderHtml)return;const blob=new Blob([builderHtml],{type:"text/html;charset=utf-8"});const url=URL.createObjectURL(blob);const a=document.createElement("a");a.href=url;a.download=(builderName.trim().replace(/[^a-z0-9-_]+/gi,"-").replace(/^-|-$/g,"")||"nexora-site")+".html";a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);setBuilderStatus("HTML export downloaded. It can be opened locally or uploaded to a static host.");};
 const publishWebsite=async()=>{if(!builderHtml)return;setBuilderBusy(true);setBuilderStatus("Publishing site through GitHub Pages…");try{const {publishSite}=await import("./ai");const r=await publishSite(builderName,builderHtml);recordPublishReport(r);setBuilderStatus((r.message||"Publish request accepted.")+(r.frontendUrl?" Frontend: "+r.frontendUrl:"")+(r.auditPersisted?" Audit report saved to the Nexora database.":" Audit report is stored in this browser; server database persistence was unavailable."));}catch(e){setBuilderStatus(e instanceof Error?e.message:"Publishing failed. Check the deployment configuration.");}finally{setBuilderBusy(false);}};
 const searchVisualAssets=(provider:"Pinterest"|"Unsplash"|"Pexels"|"Openverse")=>{const brief=builderPrompt.trim()||"premium modern website design";const q=encodeURIComponent(brief+" website design photography");const urls:Record<typeof provider,string>={Pinterest:"https://www.pinterest.com/search/pins/?q="+q,Unsplash:"https://unsplash.com/s/photos/"+q,Pexels:"https://www.pexels.com/search/"+q+"/",Openverse:"https://openverse.org/search/image?q="+q};window.open(urls[provider],"_blank","noopener,noreferrer");setBuilderStatus("Opened "+provider+" visual search. Check the original asset page and license before reuse; Pinterest is for inspiration unless reuse rights are confirmed.");};
 const copyAnswer=async(id:string,text:string)=>{try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(text)}else{const area=document.createElement("textarea");area.value=text;area.setAttribute("readonly","");area.style.position="fixed";area.style.opacity="0";area.style.pointerEvents="none";document.body.appendChild(area);area.focus();area.select();const ok=document.execCommand("copy");area.remove();if(!ok)throw new Error("Clipboard access was blocked by this browser.")}setCopyStatus(id);setTimeout(()=>setCopyStatus(current=>current===id?"":current),2200)}catch(e){setStatus(e instanceof Error?"Copy failed: "+e.message:"Copy failed. Please select and copy the text manually.")}};
 const renderAnswer=(messageId:string,text:string)=>{const parts:{kind:"text"|"code";value:string;language?:string;index:number}[]=[];const pattern=/\`\`\`([^\n\`]*)\n?([\s\S]*?)\`\`\`/g;let last=0,match:RegExpExecArray|null,index=0;while((match=pattern.exec(text))!==null){if(match.index>last)parts.push({kind:"text",value:text.slice(last,match.index),index:index++});parts.push({kind:"code",value:match[2].replace(/\n$/,""),language:match[1].trim(),index:index++});last=pattern.lastIndex}if(last<text.length||parts.length===0)parts.push({kind:"text",value:text.slice(last),index:index++});return <div className="answer-content">{parts.map(part=>part.kind==="code"?<div className="answer-code" key={messageId+"-"+part.index}>{part.language&&<div className="code-language">{part.language}</div>}<pre><code>{part.value}</code></pre><button className="small copy-answer" onClick={()=>copyAnswer(messageId+":code:"+part.index,part.value)}>{copyStatus===messageId+":code:"+part.index?"Copied ✓":"Copy code"}</button></div>:<p key={messageId+"-"+part.index}>{part.value}</p>)}{parts.filter(part=>part.kind==="code").length>1&&<button className="small copy-answer" onClick={()=>copyAnswer(messageId+":all-code",parts.filter(part=>part.kind==="code").map(part=>part.value).join("\n\n"))}>{copyStatus===messageId+":all-code"?"Copied all code ✓":"Copy all code blocks"}</button>}</div>};
 const readReferenceFile=(file:File,maxBytes:number)=>new Promise<{name:string;dataUrl:string}>((resolve,reject)=>{if(file.size>maxBytes){reject(new Error(file.name+" exceeds "+Math.round(maxBytes/1024)+" KB. Please use a smaller file."));return;}const reader=new FileReader();reader.onload=()=>resolve({name:file.name,dataUrl:String(reader.result)});reader.onerror=()=>reject(new Error("Could not read "+file.name));reader.readAsDataURL(file)}); const readReferenceImage=(file:File)=>new Promise<{name:string;dataUrl:string}>((resolve,reject)=>{if(!file.type.startsWith("image/")){reject(new Error(file.name+" is not a supported image file."));return;}const reader=new FileReader();reader.onerror=()=>reject(new Error("Could not read "+file.name));reader.onload=async()=>{let bitmap:ImageBitmap|undefined;try{bitmap=await createImageBitmap(file);const maxEdge=2560;const scale=Math.min(1,maxEdge/Math.max(bitmap.width,bitmap.height));const canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(bitmap.width*scale));canvas.height=Math.max(1,Math.round(bitmap.height*scale));const context=canvas.getContext("2d");if(!context)throw new Error("Image processor is unavailable.");context.drawImage(bitmap,0,0,canvas.width,canvas.height);const blob=await new Promise<Blob|null>(resolveBlob=>canvas.toBlob(resolveBlob,"image/webp",0.9));if(!blob)throw new Error("Could not optimize "+file.name);const encoded=await new Promise<string>((resolveData,rejectData)=>{const r=new FileReader();r.onload=()=>resolveData(String(r.result));r.onerror=()=>rejectData(new Error("Could not encode "+file.name));r.readAsDataURL(blob)});resolve({name:file.name,dataUrl:encoded});}catch(error){reject(new Error(error instanceof Error?error.message:"Could not process "+file.name));}finally{bitmap?.close();}};reader.readAsArrayBuffer(file)}); const addImageReferences=async(files:FileList|null,target:"image"|"video")=>{if(!files?.length)return;try{const existing=target==="image"?imageReferences:videoCharacterReferences;const room=Math.max(0,2-existing.length);if(!room)throw new Error("Add up to 2 reference images per generation.");const picked=Array.from(files).filter(file=>file.type.startsWith("image/")).slice(0,room);if(!picked.length)throw new Error("Choose one or more image files.");const loaded=await Promise.all(picked.map(readReferenceImage));if(target==="image")setImageReferences(items=>[...items,...loaded]);else setVideoCharacterReferences(items=>[...items,...loaded]);setStatus("Reference image(s) added and optimized automatically. Original dimensions and file size are accepted; very large images are resized proportionally for provider compatibility.");}catch(e){setStatus(e instanceof Error?e.message:"Could not add reference image.");}}; const addVoiceReference=async(file:File|null)=>{if(!file)return;if(!file.type.startsWith("audio/"))return setStatus("Choose an audio file for voice reference.");if(!voiceConsent)return setStatus("Confirm that this is your voice or that you have the speaker’s permission before importing it.");try{if(file.size>5_000_000)throw new Error("Voice samples must be 5 MB or smaller. Trim the clip or export a smaller audio file and try again.");await persistImportedVoice(file);}catch(e){setStatus(e instanceof Error?e.message:"Could not add voice reference.");}};
 const createImage=async()=>{if(!imagePrompt.trim()){setImageStatus("Describe the image first.");return;}if(aiBusy)return;setAiBusy(true);setImageBusy(true);setImageStatus("Connecting to Nexora image service…");setStatus("Crafting an original premium visual…");try{const designId=crypto.randomUUID();const prompt="Create a premium, original visual asset tailored to this request. Output aspect ratio: "+imageAspectRatio+". Target resolution: "+imageResolution+". Quality target: "+imageQuality+". File format: "+imageFormat+". Maximize detail, crisp edges, coherent composition, accurate anatomy, clean lighting and artifact-free output.  Invent a distinctive composition, silhouette, lighting, palette, materials and art direction. Do not copy, trace, or closely imitate an existing app icon, logo, brand, stock image, or reference image. Avoid generic repeated AI compositions. For app icons, use one clear original symbol, balanced negative space, crisp edges, and strong legibility at small sizes; do not add letters or words unless requested. Use any uploaded character/reference images only to preserve requested identity and visual details, not to copy unrelated artwork. For hero images and illustrations, tailor framing to the product and audience. No watermark, accidental text, or mockup frame unless requested. Fresh design key: "+designId+" (do not render this key). Avoid these elements: "+(imageNegativePrompt.trim()||"watermarks, unwanted text, distorted anatomy, blurry details, visual artifacts")+". User request: "+imagePrompt.trim();const r=await generateImage(prompt,{purpose:"original_visual_asset",designId,originalityRequired:true,referenceImages:imageReferences.map(x=>({name:x.name,dataUrl:x.dataUrl})),aspectRatio:imageAspectRatio,resolution:imageResolution,quality:imageQuality,format:imageFormat});if(!r.imageBase64)throw new Error(r.error||"Image provider returned no image data");const mime=r.mimeType||"image/png";const source=`data:${mime};base64,${r.imageBase64}`;const converted=await convertImageFormat(source,imageFormat);setImageResult([converted]);setImageStatus("Image generated successfully. Your preview is ready below.");setStatus("Image generated. Review brand fit and similarity before publishing.")}catch(e){const message=e instanceof Error?e.message:"Image generation failed. Please try again.";setImageStatus("Image generation failed: "+message);setStatus(message)}finally{setImageBusy(false);setAiBusy(false)}};
 const createVideo=async()=>{if(!videoPrompt.trim()){setVideoStatus("Describe the video first.");return;}if(aiBusy)return;const expandedPrompt=expandVideoCommands(videoPrompt);setAiBusy(true);setVideoBusy(true);setVideoStatus("Connecting to Nexora video service…");setStatus(expandedPrompt.applied.length?"Applying "+expandedPrompt.applied.length+" premium command(s) and submitting video job…":"Submitting video job…");try{const accentDirective="Spoken accent / language: "+regionalAccent+(regionalAccent.startsWith("Custom")&&customAccent.trim()?": "+customAccent.trim():"")+". Voice delivery: "+voiceStyle+". Preferred voice: "+(videoVoiceReference?(customVoiceName.trim()||"Custom voice reference"):voiceName)+". "+(customVoiceNotes.trim()?"Additional voice direction: "+customVoiceNotes.trim()+". ":"")+"Keep speech natural, culturally respectful, and non-caricatured. Preserve the same character identity, facial features, hairstyle, wardrobe, and voice across shots unless explicitly instructed otherwise.";const r=await createJob("video",{prompt:expandedPrompt.prompt+"\n\n"+(videoNegativePrompt.trim()?"Avoid these elements: "+videoNegativePrompt.trim()+". ":"")+"\n"+accentDirective+" Output quality target: "+videoQuality+". Compose for "+videoAspectRatio+" aspect ratio, "+videoResolution+" resolution, with crisp detail, stable motion, clean edges, controlled noise, consistent lighting and no compression artifacts where supported.",duration:videoLength,continuity:true,characterConsistency:true,voiceReference:Boolean(videoVoiceReference),characterReferenceImages:videoCharacterReferences.map(x=>({name:x.name,dataUrl:x.dataUrl})),voiceReferenceAudio:videoVoiceReference?.dataUrl||undefined,regionalAccent,voiceStyle,voiceName:videoVoiceReference?(customVoiceName.trim()||"Custom voice reference"):voiceName,aspectRatio:videoAspectRatio,resolution:videoResolution,quality:videoQuality});const id=(r.job as {id?:string}|undefined)?.id;if(!id)throw new Error("No video job ID returned");setStatus("Video generation queued…");const job=await waitForJob(id,undefined,1_800_000,(phase)=>setStatus("Video "+phase.replace(/[_-]/g," ")+"…"));const result=job.result as {key?:string;videoBase64?:string;format?:string}|undefined;if(result?.videoBase64){setVideoResult(`data:${result.format||"video/mp4"};base64,${result.videoBase64}`)}else if(result?.key){const asset=await getAsset(result.key);if(typeof asset.url!=="string")throw new Error("No signed video URL returned");setVideoResult(asset.url)}else throw new Error("Video job returned no playable asset");setVideoStatus("Video generated successfully. Your preview is ready below.");setStatus("Video generated successfully.")}catch(e){const message=e instanceof Error?e.message:"Video generation failed. Please try again.";setVideoStatus("Video generation failed: "+message);setStatus(message)}finally{setVideoBusy(false);setAiBusy(false)}};
 const recordVoice=async()=>{if(voiceBusy||!("MediaRecorder" in window))return setStatus("Voice input is not supported in this browser.");setVoiceBusy(true);setStatus("Listening…");try{const stream=await navigator.mediaDevices.getUserMedia({audio:true});const chunks:BlobPart[]=[];const recorder=new MediaRecorder(stream);const done=new Promise<Blob>(resolve=>{recorder.ondataavailable=e=>e.data.size&&chunks.push(e.data);recorder.onstop=()=>resolve(new Blob(chunks,{type:recorder.mimeType||"audio/webm"}))});recorder.start();setTimeout(()=>recorder.stop(),7000);const blob=await done;stream.getTracks().forEach(t=>t.stop());const reader=new FileReader();const encoded=await new Promise<string>(resolve=>{reader.onload=()=>resolve(String(reader.result).split(",")[1]||"");reader.readAsDataURL(blob)});const r=await voiceTranscribe(encoded);const text=(r as {text?:string;content?:string;message?:string}).text||(r.content||r.message||"");if(text)setChatInput(v=>(v?v+" ":"")+text);setStatus(text?"Voice captured.":"No speech detected.")}catch(e){setStatus(e instanceof Error?e.message:"Voice input unavailable.")}finally{setVoiceBusy(false)}}; const speakLast=async()=>{const last=[...chat].reverse().find(m=>m.role==="assistant");if(!last||speaking)return;setSpeaking(true);setStatus("Submitting speech job…");try{const r=await createJob("speech",{text:last.content});const id=(r.job as {id?:string}|undefined)?.id;if(!id)throw new Error("No speech job ID returned");setStatus("Generating speech…");const job=await waitForJob(id);const result=job.result as {key?:string}|undefined;if(!result?.key)throw new Error("Speech job returned no asset");const asset=await getAsset(result.key);if(typeof asset.url!=="string")throw new Error("No signed audio URL returned");const a=new Audio(asset.url);await a.play();setStatus("Speech ready.")}catch(e){setStatus(e instanceof Error?e.message:"Voice playback unavailable.")}finally{setSpeaking(false)}}; const loadMemory=async()=>{try{const r=await getMemory();setMemory(JSON.stringify(r.data??r.content??"",null,2));setMemoryStatus("Memory loaded.")}catch(e){setMemoryStatus(e instanceof Error?e.message:"Memory service unavailable.")}}; const storeMemory=async()=>{if(!memory.trim())return;try{await saveMemory(memory.trim());setMemoryStatus("Memory saved securely.")}catch(e){setMemoryStatus(e instanceof Error?e.message:"Memory service unavailable.")}};
 const runTool=async()=>{if(!toolInput.trim()){setToolStatus("Enter some text or instructions first.");return;}if(aiBusy)return;setAiBusy(true);setToolBusy(true);setToolStatus("Sending request to Nexora AI…");setToolResult("");try{const r=await aiTool(tool,toolInput);const result=r.content||r.message||JSON.stringify(r.data||{},null,2);setToolResult(result);setToolStatus("Completed successfully.")}catch(e){const message=e instanceof Error?e.message:"AI tool request failed. Please try again.";setToolResult(message);setToolStatus("Request failed: "+message)}finally{setToolBusy(false);setAiBusy(false)}};
 const runAdvertisingAgent=async()=>{if(!adsBrand.trim()||!adsProduct.trim()||!adsAudience.trim()){setAdsStatus("Enter the brand, product/service, and target audience first.");return;}setAdsBusy(true);setAdsStatus("Building a premium advertising concept…");setAdsOutput("");setAdsImage("");const brief={brand:adsBrand.trim(),productOrService:adsProduct.trim(),targetAudience:adsAudience.trim(),campaignGoal:adsGoal,platform:adsPlatform,visualDirection:adsColours,requiredDetails:adsDetails.trim(),avoid:adsAvoid.trim()};try{const r=await aiTool("advertising",brief);const output=r.content||r.message||JSON.stringify(r.data??r,null,2);setAdsOutput(output);setAdsStatus("Creative brief ready. Review the copy and generate a visual when you are satisfied.");}catch(e){setAdsStatus(e instanceof Error?e.message:"Advertising agent unavailable. Check Nexora AI provider configuration.");}finally{setAdsBusy(false);}};
 const generateAdvertisingImage=async()=>{if(!adsOutput.trim())return;setAdsImageBusy(true);setAdsStatus("Generating the advertising visual…");try{const prompt="Create a finished premium professional advertising design, not a mockup. Colourful, polished, conversion-focused and platform-ready. Use clear visual hierarchy, bold highly readable typography, strong composition, realistic high-quality imagery, professional lighting, balanced spacing and an intentional colour palette. Preserve exact brand spelling and any provided copy; do not invent contact details, prices, endorsements or claims. Avoid clutter, distorted logos, watermarks and gibberish text. Campaign brief:\n"+JSON.stringify({brand:adsBrand,productOrService:adsProduct,targetAudience:adsAudience,goal:adsGoal,platform:adsPlatform,visualDirection:adsColours,requiredDetails:adsDetails,creativeConcept:adsOutput});const r=await generateImage(prompt,{aspectRatio:adsPlatform.toLowerCase().includes("story")||adsPlatform.toLowerCase().includes("tiktok")?"9:16":"4:5",resolution:"2K",quality:"premium",format:"png"});const image=r.images?.[0]||r.imageUrl||(r.imageBase64?"data:"+(r.mimeType||"image/png")+";base64,"+r.imageBase64:"");if(!image)throw new Error(r.error||"The image provider returned no usable image. Review provider configuration and try again.");setAdsImage(image);setAdsStatus("Advertising visual generated. Review the result before publishing.");}catch(e){setAdsStatus(e instanceof Error?e.message:"Image generation failed. Check image provider configuration.");}finally{setAdsImageBusy(false);}};
  const runLocalization=async()=>{if(!localizeInput.trim()||!targetLanguages.length)return;setLocalizeBusy(true);setLocalizeStatus("Translating and localizing…");setLocalizeOutput("");try{const dialects:Record<string,string>={};if(targetDialect)targetLanguages.forEach(language=>{dialects[language]=targetDialect});const output=await localizeText({text:localizeInput,sourceLanguage,targetLanguages,dialects,mode:localizeMode,context:localizeContext,glossary:localizeGlossary});setLocalizeOutput(output);setLocalizeStatus("Localization completed. Review the result for names, numbers, cultural nuance and dialect accuracy before publishing.")}catch(e){setLocalizeStatus(e instanceof Error?e.message:"Localization request failed.")}finally{setLocalizeBusy(false)}};
